41	const PROCESSING_FEE = 5;
42	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
43	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
44	
45	/** The MHPCO price list; only the types pinned down by tests so far. */
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	};
53	
54	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
55	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
56	
57	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
58	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
59	
60	const basePremiumFor = (item: Item): number => BASE_PREMIUMS[item.type];
61	
62	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
63	
64	const quote = (step: QuoteStep): StepResult => {
65	  const policyBasePremium = sum(step.items.map(basePremiumFor));
66	  const afterPolicyModifiers = policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
67	  return { premium: roundUpToWholeG(afterPolicyModifiers + PROCESSING_FEE) };
68	};
69	
70	const runStep = (step: Step): StepResult => {
71	  if (step.op === "quote") return quote(step);
72	  throw new Error(`Unsupported step: ${step.op}`);
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioResult => ({
76	  results: scenario.steps.map(runStep),
77	});
